import http from 'k6/http';

// Load test for the Symfony FPM benchmark: closed-loop load (VUs = connections) rotating
// through the generated route paths. The config (generated by gen-bench.py) is passed in
// via the CONFIG_JSON env var; TARGET/VUS/DURATION are set per run by run.sh.
const config = JSON.parse(__ENV.CONFIG_JSON);
const target = __ENV.TARGET;
const paths = config.paths;
let i = 0;

export const options = {
  vus: Number(__ENV.VUS),
  duration: __ENV.DURATION,
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(50)', 'p(99)'],
};

export default function () {
  i = (i + 1) % paths.length;
  http.get(target + paths[i]);
}

// Emit a compact JSON summary on stdout (picked up by run.sh / report.py)
export function handleSummary(data) {
  const values = data.metrics.http_req_duration.values;
  const requests = data.metrics.http_reqs.values.count;
  const summary = {
    rps: requests / (data.state.testRunDurationMs / 1000),
    p50: values['p(50)'],
    p99: values['p(99)'],
    errors: Math.round(data.metrics.http_req_failed.values.rate * requests),
  };
  return { stdout: JSON.stringify(summary, null, 2) };
}
